$db=db();$lesson=query_one("SELECT l.id FROM lessons l JOIN grades g ON g.id=l.grade_id JOIN subjects s ON s.id=l.subject_id WHERE g.grade_number=10 AND s.name_en='Buddhism' AND l.medium='Sinhala' AND l.display_order=4 AND l.title_si='කුසල් සිත් වැඩි දියුණු කරමු' AND l.status='active' LIMIT 1");if(!$lesson)throw new RuntimeException('Grade 10 Sinhala Buddhism lesson 4 was not found.');$quiz=query_one("SELECT id FROM quizzes WHERE lesson_id=? AND status='active' ORDER BY id LIMIT 1",'i',[(int)$lesson['id']]);if(!$quiz)throw new RuntimeException('Grade 10 Sinhala Buddhism lesson 4 quiz was not found.');$quizId=(int)$quiz['id'];$db->begin_transaction();
try{$answers=$db->prepare("DELETE qa FROM quiz_answers qa JOIN quiz_questions qq ON qq.id=qa.question_id WHERE qq.quiz_id=? AND qq.activity_type='challenge'");$answers->bind_param('i',$quizId);$answers->execute();$delete=$db->prepare("DELETE FROM quiz_questions WHERE quiz_id=? AND activity_type='challenge'");$delete->bind_param('i',$quizId);$delete->execute();$insert=$db->prepare("INSERT INTO quiz_questions(quiz_id,activity_type,question_si,option_a_si,option_b_si,option_c_si,option_d_si,correct_option,explanation_si,display_order,status) VALUES(?,'challenge',?,?,?,?,?,?,?,?,'active')");foreach($questions as $i=>$q){[$text,$options,$correct,$explanation]=$q;$order=$i+1;$insert->bind_param('isssssssi',$quizId,$text,$options[0],$options[1],$options[2],$options[3],$correct,$explanation,$order);if(!$insert->execute())throw new RuntimeException($insert->error);}$db->query("UPDATE quizzes SET title_si='4 වන පාඩම — MCQ ප්‍රශ්න 30',timer_minutes=30,pass_mark=50 WHERE id=$quizId");$count=(int)(query_one("SELECT COUNT(*) total FROM quiz_questions WHERE quiz_id=? AND activity_type='challenge' AND status='active'",'i',[$quizId])['total']??0);if($count!==30)throw new RuntimeException("Expected 30 MCQs, found $count.");$db->commit();echo "Grade 10 Buddhism lesson 4 replaced with 30 MCQs.\n";}catch(Throwable $error){$db->rollback();throw $error;}
